cases.iac_payload:
resource "aws_s3_bucket" "data" {
  bucket = "my-data"
}
resource "aws_security_group" "web" {
  ingress {
    from_port = 22
    to_port = 22
    protocol = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

resource "google_container_cluster" "main" {
  name     = "my-gke"
  location = "us-central1"
  remove_default_node_pool = true
  initial_node_count = 1
  master_authorized_networks_config {
    cidr_blocks = []
  }
}

resource "azurerm_kubernetes_cluster" "main" {
  name                = "my-aks"
  location            = "East US"
  dns_prefix          = "aks"
  default_node_pool {
    name       = "default"
    vm_size    = "Standard_D2s_v3"
    enable_auto_scaling = false
  }
  role_based_access_control {
    enabled = false
  }
}

resource "aws_lambda_function" "api" {
  function_name = "api"
  runtime       = "python3.9"
  handler       = "index.handler"
  role          = aws_iam_role.lambda.arn
  vpc_config {
    subnet_ids = [aws_subnet.private.id]
  }
  environment {
    variables = {
      DB_PASSWORD = "supersecret123"
    }
  }
}

resource "google_cloud_run_v2_service" "api" {
  name     = "api"
  location = "us-central1"
  template {
    containers {
      image = "gcr.io/project/api:latest"
      env {
        name  = "API_KEY"
        value = "hardcoded-secret"
      }
    }
  }
  traffics {
    percent = 100
    latest_revision = true
  }
}

resource "azurerm_container_app" "api" {
  name                = "api"
  resource_group_name = azurerm_resource_group.rg.name
  managed_environment_id = azurerm_container_app_managed_environment.env.id
  configuration {
    ingress {
      external_enabled = true
      target_port      = 8080
    }
    secrets {
      name  = "db-password"
      value = "plaintext-password"
    }
  }
}

resource "aws_ecs_service" "api" {
  name            = "api"
  cluster         = aws_ecs_cluster.main.arn
  task_definition = aws_ecs_task_definition.api.arn
  desired_count   = 1
  deployment_controller {
    type = "ECS"
  }
}
resource "aws_ecs_task_definition" "api" {
  family                   = "api"
  network_mode             = "bridge"
  container_definitions    = jsonencode([{ name = "api", image = "api:latest", cpu = 1024, memory = 2048 }])
}

resource "aws_s3_bucket" "data" { bucket = "data" }
resource "azurerm_storage_account" "data" { name = "data" account_tier = "Standard" account_replication_type = "LRS" }
resource "google_storage_bucket" "data" { name = "data" location = "US" }
